#imputation 06_05_2025import numpy as npimport pandas as pdimport matplotlib.pyplot as plt#import dataclownfish_data = pd.read_excel('/Users/ggraham/Desktop/multiome_poa/Reference/Complete Data Frame (Hormones, Behavior, Size, Gonads) GG.xlsx')clownfish_data_known_sex = clownfish_data[(clownfish_data['Status'].isin(['M','F','D','E']))]clown_x = clownfish_data_known_sex[['mass_final_cm','Log_11KT']]clown_y = clownfish_data_known_sex[['Status']]    """There are two NANs in clown_x, in the past I have filled them in with the mean male and female, but we can do betterMy instinct before reading the chapter is you can use a linear regression between two variables to predic the missing values"""clown_x.isnull().sum()"""it is recommended to use NumPyarrays when possible. Note that you can always access the underlying NumPy array of aDataFrame via the values attribute before you feed it into a scikit-learn estimator:    df.values()"""## approach one, drop na, this removes any rows with NAsclown_x_dropna = clown_x.dropna(axis = 0)# we can also do columns with axis =1 ### imputation ####from sklearn.impute import SimpleImputer## mean imputation ###the most basic form of imputation is mean imputation which uses the mean form that columnmean_imputer = SimpleImputer(missing_values = np.nan,# specify numpy NAs                             strategy = 'mean' # replace with the mean                             )mean_imputer = mean_imputer.fit(clown_x.values)mean_imputed_data = mean_imputer.transform(clown_x.values)#imputes to 2.336 11KT#this can also be done likemean_imputed_data_2 =  clown_x.fillna(clown_x.mean())# which produces the same result## categorical data ##clownfish_data_na_sex = clownfish_data_known_sex[['mass_final_cm','Log_11KT', 'Status']]clownfish_data_na_sex['Status'] = np.where(clownfish_data_known_sex['Status'].isin(['M','F']), clownfish_data_known_sex['Status'],"NA" )#alright now I have some missing categorical data#first need to map labelsfrom sklearn.preprocessing import LabelEncoderclass_le = LabelEncoder()clownfish_data_na_sex['numeric_status']=class_le.fit_transform(clownfish_data_na_sex['Status'].values)##one hot encoding ##"""So the idea here is instead of doing red = 1, green = 2, blue =3 which will not be accurate formodels, we create 3 columns which are binary and mutually exclusivesuch that red is 1 in the red column, blue is 1 in the blue column, and green is 1in the green column"""from sklearn.preprocessing import OneHotEncoderclownfish_data_na_sex_one_hot = clownfish_data_na_sex.valuesclown_ohe = OneHotEncoder()clown_ohe.fit_transform(clownfish_data_na_sex_one_hot[:, 2].reshape(-1, 1)).toarray()#can also do clownfish_data_na_sex_one_hot_2 = pd.get_dummies(clownfish_data_na_sex[['mass_final_cm','Log_11KT', 'Status']])#in the book this produces a 1 or a 0 rather than a true or a 0 IDK why